// Safe date parser
function toDate(value) {
  if (!value) return null;
  const d = new Date(value);
  return isNaN(d.getTime()) ? null : d;
}

// Sort by Expense Date (OLD → NEW, recent last)
parsedItems.sort((a, b) => {
  const da = toDate(a.json["Expense Date"]);
  const db = toDate(b.json["Expense Date"]);

  if (da && db) return da - db;   // oldest first
  if (da && !db) return -1;       // dated entries first
  if (!da && db) return 1;
  return 0;                       // both missing/invalid
});

return parsedItems;

const items = $input.all();

function money(value) {
  if (value === null || value === undefined || value === '') {
    return '₹0';
  }

  return `₹${Number(value).toLocaleString('en-IN', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })}`;
}


// --------------------------------------------------
// 1. PARSE AI SALES OUTPUT
// --------------------------------------------------

const parsedItems = items.map(item => {
  const rawText = item.json.output?.[0]?.content?.[0]?.text;

  if (!rawText) {
    throw new Error('AI output text not found');
  }

  let parsed;

  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    throw new Error('Invalid JSON from AI for sales extraction');
  }

  return {
    json: parsed
  };
});


