const pdfItems = $input.all();
const salesItems = $('Code Sales').all();

return pdfItems.map((item, index) => {
  const sales = salesItems[index]?.json || {};

  const customerName = String(sales.customer_name || 'Unknown-Customer')
    .trim()
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  const orderId = String(sales.order_id || 'Unknown-Order')
    .trim()
    .replace(/[^a-zA-Z0-9-]/g, '');

  const date = sales.order_date?.iso
    ? sales.order_date.iso.split('T')[0]
    : 'Unknown-Date';

  if (item.binary?.data) {
    item.binary.data.fileName =
      `${customerName}_${orderId}_${date}.pdf`;

    item.binary.data.fileExtension = 'pdf';
    item.binary.data.mimeType = 'application/pdf';
  }

  return item;
});

const uploadedItems = $input.all();
const salesItems = $('Code Sales').all();

return uploadedItems.map((item, index) => {
  const sales = salesItems[index]?.json || {};

  return {
    json: {
      ...sales,

      // Google Drive details
      drive_file_id: item.json.id || '',
      drive_file_name: item.json.name || '',
      drive_web_view_link: item.json.webViewLink || '',
    }
  };
});
